// Compute poll window
const staticData = $getWorkflowStaticData('global');
const now = new Date();
const nowIso = now.toISOString();
const lastPollIso = staticData.lastPollIso || new Date(now.getTime() - 35 * 60 * 1000).toISOString();
return [{ json: { since: lastPollIso, until: nowIso } }];

// Process each lead with recent update; dedupe + detect outcome change; create ConvTracker row
const SS_API_TOKEN = '<REDACTED>';
const SS_ACCOUNT_ID = '52739';
const SS_APP_ID = '69d92c38b801d747e74629d1';
const LCO_FIELD = 'cf_ErvvcNuLOk5MoC2Hee0M5lOMhroId3YsAK1VGY8M5zH';

const map = {
  'Owner - Booked':             { outcome: 'Interested',     booked: true  },
  'Owner - Talked':             { outcome: 'Interested',     booked: false },
  'Owner - Maybe':              { outcome: 'Maybe',          booked: false },
  'Owner - Callback Requested': { outcome: 'Maybe',          booked: false },
  'Owner - Not Interested':     { outcome: 'Not Interested', booked: false },
  'Voicemail':                  { outcome: 'No Contact',     booked: false },
  'No Answer':                  { outcome: 'No Contact',     booked: false },
  'Wrong Number':               { outcome: 'No Contact',     booked: false },
  'Do Not Call':                { outcome: 'Not Interested', booked: false },
  'Gatekeeper':                 { outcome: 'Gatekeeper',     booked: false },
  'Non-Decision Maker (NDM) Interested': { outcome: 'Interested', booked: false },
  'Left Voicemail':              { outcome: 'LVM',            booked: false },
  'Voice Agent':                 { outcome: 'No Contact',     booked: false },
  'Invalid':                     { outcome: 'No Contact',     booked: false },
  'Hung Up - Owner':             { outcome: 'Not Interested', booked: false }
};

const response = $input.item.json;
const leads = response.data || [];
const today = new Date().toISOString().split('T')[0];
const results = [];

for (const lead of leads) {
  const currOutcome = lead[LCO_FIELD] || lead['custom.' + LCO_FIELD];
  if (!currOutcome) {
    results.push({ action: 'skip_no_outcome', lead_id: lead.id });
    continue;
  }

  // Single SS query: pull all history rows for this lead
  const historyQuery = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://app.smartsuite.com/api/v1/applications/${SS_APP_ID}/records/list/`,
    headers: {
      'Authorization': `Token ${SS_API_TOKEN}`,
      'ACCOUNT-ID': SS_ACCOUNT_ID,
      'Content-Type': 'application/json'
    },
    body: {
      filter: {
        operator: 'and',
        fields: [{ field: 'close_lead_id', comparison: 'is', value: lead.id }]
      },
      hydrated: false
    }
  });

  const rows = (historyQuery.items || []);

  // Dedupe: today's row with this outcome already exists?
  const dupeToday = rows.find(r => {
    const d = r.conversation_date;
    const dateStr = (d && typeof d === 'object') ? (d.date || '').slice(0, 10) : String(d || '').slice(0, 10);
    return dateStr === today && (r.notes || '').includes('[' + currOutcome + ']');
  });
  if (dupeToday) {
    results.push({ action: 'skip_duplicate', lead_id: lead.id, outcome: currOutcome });
    continue;
  }

  // Detect prev outcome from most recent row
  rows.sort((a, b) => {
    const da = (a.conversation_date && a.conversation_date.date) || '';
    const db = (b.conversation_date && b.conversation_date.date) || '';
    return db.localeCompare(da);
  });
  const prevRow = rows[0];
  const prevMatch = prevRow ? (prevRow.notes || '').match(/^\[([^\]]+)\]/) : null;
  const prevOutcome = prevMatch ? prevMatch[1] : null;

  if (prevOutcome === currOutcome) {
    results.push({ action: 'skip_no_change', lead_id: lead.id, outcome: currOutcome });
    continue;
  }

  const m = map[currOutcome] || { outcome: 'Not Interested', booked: false };
  const leadName = lead.display_name || lead.name || 'Unknown';
  const decisionMaker = (lead.contacts && lead.contacts[0] && lead.contacts[0].name) || '';

  const created = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://app.smartsuite.com/api/v1/applications/${SS_APP_ID}/records/`,
    headers: {
      'Authorization': `Token ${SS_API_TOKEN}`,
      'ACCOUNT-ID': SS_ACCOUNT_ID,
      'Content-Type': 'application/json'
    },
    body: {
      title: leadName + ' - ' + currOutcome,
      company_name: leadName,
      decision_maker: decisionMaker,
      conversation_date: today,
      outcome: m.outcome,
      call_booked: m.booked,
      notes: '[' + currOutcome + ']' + (prevOutcome ? ' (was: ' + prevOutcome + ')' : ' (first outcome)'),
      last_call_outcome: currOutcome,
      close_lead_id: lead.id
    }
  });

  results.push({
    action: 'created',
    lead_id: lead.id,
    last_call_outcome: currOutcome,
    prev_outcome: prevOutcome,
    mapped: m,
    ss_record_id: created.id,
    source: 'polling'
  });
}

// Update last poll timestamp on success
const staticData2 = $getWorkflowStaticData('global');
staticData2.lastPollIso = $('Compute Poll Window').item.json.until;

return results.length ? results.map(r => ({ json: r })) : [{ json: { action: 'no_leads_updated' } }];

