// Parse Calendly invitee.created payload
const raw = $input.item.json;
const body = raw.body || raw;
const event = body.event;

if (event !== 'invitee.created') {
  return [{ json: { action: 'skip_wrong_event', event } }];
}

const p = body.payload || {};
const e = p.scheduled_event || {};

// Build Q&A block for notes
let qa_lines = [];
if (Array.isArray(p.questions_and_answers) && p.questions_and_answers.length > 0) {
  qa_lines = p.questions_and_answers.map(qa => {
    const q = qa.question || ('Q' + (qa.position || '?'));
    const a = qa.answer || '(blank)';
    return `${q}: ${a}`;
  });
}

const notes_body = [
  'Calendly Booking',
  `Event: ${e.name || 'unknown'}`,
  `Start: ${e.start_time || ''}`,
  `Invitee URI: ${p.uri || ''}`,
  `Event URI: ${e.uri || ''}`,
  '',
  'Q&A:',
  qa_lines.length > 0 ? qa_lines.join('\n') : '(none submitted)'
].join('\n');

const start_time = e.start_time || '';
const start_date = start_time.slice(0, 10); // YYYY-MM-DD for datefield

return [{
  json: {
    event_type: event,
    name: p.name || 'Unknown Invitee',
    email: p.email || '',
    scheduled_event_name: e.name || '',
    start_time,
    start_date,
    invitee_uri: p.uri || '',
    event_uri: e.uri || '',
    notes_body,
    qa_count: (p.questions_and_answers || []).length
  }
}];

// Upsert Pipeline record from Calendly booking
// Hydrates from Close lead search: company_name, contact_phone, close_lead_id.
// All hydrated fields are written on BOTH create AND update paths so existing
// records get backfilled if M3 is re-fired for them.

const SS_API_TOKEN = '<REDACTED>';
const SS_ACCOUNT_ID = '52739';
const SS_APP_ID = '6908636826cfbf4238a34f31';

// Parsed Calendly data from upstream Parse node
const p = $('Parse Invitee Payload').item.json;

if (p.action && String(p.action).startsWith('skip_')) {
  return [{ json: p }];
}

if (!p.email) {
  return [{ json: { action: 'skip_no_email', payload: p } }];
}

// --- Hydrate from Close lead search response ---
let close_lead_id = '';
let close_company_name = '';
let close_phone = '';
let close_url = '';

try {
  const closeResp = $input.item.json;
  if (closeResp && !closeResp.error) {
    const leads = closeResp?.data || [];
    if (leads.length > 0) {
      const lead = leads[0];
      close_lead_id = lead.id || '';
      close_company_name = lead.display_name || lead.name || '';
      close_url = lead.url || '';
      // Find first contact whose email matches the booking email; fallback to first contact
      const contacts = lead.contacts || [];
      let chosen = contacts.find(c =>
        (c.emails || []).some(e => (e.email || '').toLowerCase() === p.email.toLowerCase())
      ) || contacts[0];
      if (chosen) {
        const phones = chosen.phones || [];
        if (phones.length > 0) {
          close_phone = phones[0].phone || '';
        }
      }
    }
  }
} catch (e) {
  // Silent — fall through with empty hydration
}

// Lookup existing Pipeline record by contact_email
const lookupResp = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${SS_APP_ID}/records/list/`,
  headers: {
    'Authorization': `Token ${SS_API_TOKEN}`,
    'ACCOUNT-ID': SS_ACCOUNT_ID,
    'Content-Type': 'application/json'
  },
  body: {
    filter: {
      operator: 'and',
      fields: [{ field: 'contact_email', comparison: 'is', value: p.email }]
    }
  }
});

const existing = (lookupResp.items || []);

// Common fields written on BOTH create AND update.
// company_name falls back to invitee name if Close lookup missed.
const common = {
  title: `${close_company_name || p.name} — Calendly Booking`,
  contact_email: p.email,
  contact_name: p.name,
  company_name: close_company_name || p.name,
  deal_stage: 'Booked',
  next_action: 'Prepare for booked call',
  next_action_date: p.start_date || null,
  notes: p.notes_body,
  calendly_invitee_uri: p.invitee_uri || ''
};

// Hydrated optional fields — only write if Close lookup hit
if (close_lead_id) common.close_lead_id = close_lead_id;
if (close_phone) common.contact_phone = [close_phone];

if (existing.length > 0) {
  const recordId = existing[0].id;
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `https://app.smartsuite.com/api/v1/applications/${SS_APP_ID}/records/${recordId}/`,
    headers: {
      'Authorization': `Token ${SS_API_TOKEN}`,
      'ACCOUNT-ID': SS_ACCOUNT_ID,
      'Content-Type': 'application/json'
    },
    body: common
  });
  return [{ json: {
    action: 'updated',
    email: p.email,
    ss_record_id: recordId,
    deal_stage: 'Booked',
    company_name: common.company_name,
    contact_phone: close_phone || null,
    close_lead_id: close_lead_id || null,
    source: 'calendly_webhook'
  }}];
} else {
  const created = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://app.smartsuite.com/api/v1/applications/${SS_APP_ID}/records/`,
    headers: {
      'Authorization': `Token ${SS_API_TOKEN}`,
      'ACCOUNT-ID': SS_ACCOUNT_ID,
      'Content-Type': 'application/json'
    },
    body: { ...common }
  });
  return [{ json: {
    action: 'created',
    email: p.email,
    ss_record_id: created.id,
    deal_stage: 'Booked',
    company_name: common.company_name,
    contact_phone: close_phone || null,
    close_lead_id: close_lead_id || null,
    source: 'calendly_webhook'
  }}];
}

