// PATCH SS Pipeline record: set no_show_processed=true if Calendly returned 201 or 409.
const SS_API_TOKEN = '<REDACTED>';
const SS_ACCOUNT_ID = '52739';
const PIPELINE_APP_ID = '6908636826cfbf4238a34f31';

// Pull merged context: Calendly response + the original record_id / invitee_uri from upstream IF-true branch.
const item = $input.item.json;
const status = item.statusCode;
const recordId = $('Query No-Shows').item.json.record_id;
const inviteeUri = $('Query No-Shows').item.json.invitee_uri;
const title = $('Query No-Shows').item.json.title;

const ok = (status === 201 || status === 200 || status === 409);
if (!ok) {
  return [{ json: { record_id: recordId, title, invitee_uri: inviteeUri, calendly_status: status, action: 'calendly_failed_skipping_patch', body: item.body } }];
}

const patchRes = await this.helpers.httpRequest({
  method: 'PATCH',
  url: `https://app.smartsuite.com/api/v1/applications/${PIPELINE_APP_ID}/records/${recordId}/`,
  headers: {
    'Authorization': `Token ${SS_API_TOKEN}`,
    'ACCOUNT-ID': SS_ACCOUNT_ID,
    'Content-Type': 'application/json'
  },
  body: { no_show_processed: true }
});

return [{ json: { record_id: recordId, title, invitee_uri: inviteeUri, calendly_status: status, calendly_already_marked: status === 409, ss_patched: true } }];

// Webhook entry: fetch the single Pipeline record by ID, normalize to same shape as Query No-Shows.
