const claudeResp = $input.first().json;
const content = claudeResp.content?.[0]?.text || claudeResp.content || '';

const now = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric', timeZone: 'America/New_York' });
const time = new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', timeZone: 'America/New_York' });

if (content.trim() === 'ALL_CLEAR' || content.includes('ALL_CLEAR')) {
  return [{ json: { 
    slackMessage: ':white_check_mark: *Slack Ops Supervisor* — ' + now + ' ' + time + '\nAll channels scanned. No issues detected. Ops running clean.',
    hasCritical: false,
    issueCount: 0
  }}];
}

// Parse issues
const lines = content.split('\n').filter(l => l.includes('|'));
let criticals = [];
let warnings = [];
let infos = [];

for (const line of lines) {
  const parts = line.split('|').map(p => p.trim());
  if (parts.length < 4) continue;
  const [type, channel, severity, desc] = parts;
  const emoji = severity === 'critical' ? ':red_circle:' : severity === 'warning' ? ':large_yellow_circle:' : ':white_circle:';
  const formatted = emoji + ' *' + type + '* — ' + channel + '\n> ' + desc;

  if (severity === 'critical') criticals.push(formatted);
  else if (severity === 'warning') warnings.push(formatted);
  else infos.push(formatted);
}

const total = criticals.length + warnings.length + infos.length;
let msg = ':eyes: *Slack Ops Supervisor* — ' + now + ' ' + time + '\n';
msg += total + ' issue' + (total !== 1 ? 's' : '') + ' detected';
if (criticals.length > 0) msg += ' (:red_circle: ' + criticals.length + ' critical)';
msg += '\n\n';

if (criticals.length > 0) msg += '*CRITICAL*\n' + criticals.join('\n') + '\n\n';
if (warnings.length > 0) msg += '*WARNINGS*\n' + warnings.join('\n') + '\n\n';
if (infos.length > 0) msg += '*INFO*\n' + infos.join('\n') + '\n\n';

msg += '_Automated scan of ' + ($input.first().json.messageCount || 'all') + ' recent messages across client and internal channels._';

return [{ json: { slackMessage: msg, hasCritical: criticals.length > 0, issueCount: total } }];

