  ssGet.call(this, CLI_APP)
]);

const labels = {"1": "Not Started", "2": "In Progress", "3": "Complete"};
const clientSummaries = [];

for (const cli of (cliData.items || [])) {
  const name = cli.title || "Unknown";
  const clientStatus = cli.client_status?.value || cli.client_status || "unknown";

  const ob = (obData.items || []).find(r => r.title === name);
  let obSummary = "No onboarding record";
  let obPhase = "";
  let blockers = [];

  if (ob) {
    const obStatus = ob.status?.value || ob.status || "unknown";
    let doneCount = 0;
    let totalSteps = 0;

    const acctSteps = ["business_portfolio_access","ad_account_visible","facebook_page_confirmed","instagram_connected","meta_ads_app_installed"];
    const leadSteps = ["leads_access_confirmed","lead_notifications_set","lead_centre_to_crm","lead_destination_confirmed","fb_lead_centre_connected"];
    const videoSteps = ["video_brief_sent","videos_received","ad_creative_ready","videos_edited"];
    const launchSteps = ["campaign_built","qa_passed","campaign_launched","launch_notification_sent"];

    for (const [k, v] of Object.entries(ob)) {
      if (k.startsWith("step_")) {
        const val = String(v);
        totalSteps++;
        if (val === "3") doneCount++;
        else if (val === "1") {
          const field = k.replace("step_", "");
          if (acctSteps.includes(field)) blockers.push("Account Access: " + field);
          else if (leadSteps.includes(field)) blockers.push("Lead Setup: " + field);
          else if (videoSteps.includes(field)) blockers.push("Videos: " + field);
          else if (launchSteps.includes(field)) blockers.push("Launch: " + field);
        }
      }
    }
    obSummary = doneCount + "/" + totalSteps + " steps done, status: " + obStatus;

    if (blockers.some(b => b.startsWith("Account"))) obPhase = "Blocked at: Account Access";
    else if (blockers.some(b => b.startsWith("Lead"))) obPhase = "Blocked at: Lead Setup";
    else if (blockers.some(b => b.startsWith("Video"))) obPhase = "Blocked at: Videos";
    else if (blockers.some(b => b.startsWith("Launch"))) obPhase = "Blocked at: Campaign Launch";
    else obPhase = "All steps complete";
  }

  const camps = (campData.items || []).filter(c => String(c.title || "").includes(name));
  let campSummary = "No campaigns";
  if (camps.length > 0) {
    campSummary = camps.map(c => (c.title || "Untitled") + " [" + (c.status?.value || c.status || "?") + "]").join("; ");
  }

  clientSummaries.push({
    client: name,
    clientStatus,
    onboarding: obSummary,
    currentPhase: obPhase,
    topBlockers: blockers.slice(0, 5),
    campaigns: campSummary
  });
}

return [{
  json: {
    smartsuiteContext: clientSummaries,
    fetchedAt: new Date().toISOString()
  }
}];

