const SLACK_HEADERS = {
  'Authorization': `Bearer ${SLACK_BOT_TOKEN}`,
  'Content-Type': 'application/json'
};

const ss = (method, path, body) => this.helpers.httpRequest({
  method,
  url: `https://app.smartsuite.com/api/v1${path}`,
  headers: SS_HEADERS,
  body
});

const slack = (endpoint, body) => this.helpers.httpRequest({
  method: 'POST',
  url: `https://slack.com/api/${endpoint}`,
  headers: SLACK_HEADERS,
  body
});

// --- DETERMINE MODE ---
let rows = [];
const input = $input.first().json;
const body = input.body || input;
const recordId = body.record_id;

if (recordId) {
  // WEBHOOK MODE: process this specific record
  const r = await ss('GET', `/applications/${PIPELINE_APP}/records/${recordId}/`);
  if (r.deal_stage !== 'Won') {
    return [{ json: { count: 0, processed: [], mode: 'webhook', note: 'deal_stage is not Won' } }];
  }
  const flag = r.won_processed;
  if (flag === true || flag === 'true' || flag === 1 || flag === '1') {
    return [{ json: { count: 0, processed: [], mode: 'webhook', note: 'already_processed' } }];
  }
  rows = [r];
} else {
  // POLL MODE: fetch all Won records not yet processed
  const resp = await ss('POST', `/applications/${PIPELINE_APP}/records/list/`, {
    hydrated: true,
    filter: {
      operator: 'and',
      fields: [
        { field: 'deal_stage', comparison: 'is', value: 'Won' }
      ]
    }
  });
  const allWon = (resp.items || []);
  rows = allWon.filter(r => {
    const flag = r.won_processed;
    return flag !== true && flag !== 'true' && flag !== 1 && flag !== '1';
  });
  if (rows.length === 0) {
    return [{ json: { count: 0, processed: [], mode: 'poll' } }];
  }
}

const results = [];

for (const r of rows) {
  const pipelineId = r.id;
  const companyName = r.company_name || r.title || 'Unknown Client';
  const contactName = r.contact_name || '';
  const rawEmail = r.contact_email;
  const contactEmail = Array.isArray(rawEmail) ? (rawEmail[0] || '') : (rawEmail || '');

  const slug = companyName
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .substring(0, 20)
    .replace(/-$/, '');

  const result = {
    ok: false,
    mode: recordId ? 'webhook' : 'poll',
    pipeline_id: pipelineId,
    company_name: companyName,
    contact_email: contactEmail,
    slug,
    client_channel: `client-${slug}`,
    team_channel: `team-${slug}`,
    client_id: null,
    onboarding_id: null,
    public_channel_id: null,
    private_channel_id: null,
    slack_ok: false,
    error: null
  };

  try {
    // 1. Create SS Client record
    const inputNiche = (body && body.niche) || DEFAULT_NICHE;
    // priority is the slug of the Niche field on Clients app. Map label → numeric value.
    const NICHE_LABEL_TO_VALUE = { 'REI': '2', 'Notes': '3', 'Health': '4', 'Construction': '5', 'Other': '6' };
    const nicheValue = NICHE_LABEL_TO_VALUE[inputNiche] || '2';
    const clientPayload = { title: companyName, contact_name: contactName, status: "Active", priority: nicheValue };
    if (contactEmail) clientPayload.contact_email = contactEmail;
    const clientResp = await ss('POST', `/applications/${CLIENTS_APP}/records/`, clientPayload);
    const clientId = clientResp.id;
    if (!clientId) throw new Error(`Client create failed: ${JSON.stringify(clientResp).substring(0, 200)}`);
    result.client_id = clientId;

    // 2. Create SS Onboarding record linked to Client
    const onboardingResp = await ss('POST', `/applications/${ONBOARDING_APP}/records/`, {
      title: companyName,
      client: [clientId]
    });
    const onboardingId = onboardingResp.id;
    if (!onboardingId) throw new Error(`Onboarding create failed: ${JSON.stringify(onboardingResp).substring(0, 200)}`);
    result.onboarding_id = onboardingId;

    // 3. Create client Slack channel (private — bot lacks channels:manage for public)
    const slackErrors = [];
    let publicChannelId = null;
    let privateChannelId = null;

    const pubResp = await slack('conversations.create', { name: `client-${slug}`, is_private: true });
    if (pubResp.ok) {
      publicChannelId = pubResp.channel.id;
      result.public_channel_id = publicChannelId;
    } else {
      slackErrors.push(`Client channel: ${pubResp.error}`);
    }

    // 4. Create team Slack channel (private)
    const privResp = await slack('conversations.create', { name: `team-${slug}`, is_private: true });
    if (privResp.ok) {
      privateChannelId = privResp.channel.id;
      result.private_channel_id = privateChannelId;
    } else {
      slackErrors.push(`Team channel: ${privResp.error}`);
    }

    // 5. Invite Andrew to both channels
    for (const chId of [publicChannelId, privateChannelId].filter(Boolean)) {
      const inv = await slack('conversations.invite', { channel: chId, users: ANDREW_SLACK_ID });
      if (!inv.ok && inv.error !== 'already_in_channel') {
        slackErrors.push(`Invite Andrew to ${chId}: ${inv.error}`);
      }
    }

    // 6. Post welcome message to client channel
    const scriptDocId = SCRIPT_DOC_BY_NICHE[inputNiche] || SCRIPT_DOC_BY_NICHE[DEFAULT_NICHE];
    const scriptLine = scriptDocId
      ? `:clipboard: *Your Video Script Library:*\n<https://drive.google.com/file/d/${scriptDocId}/view?usp=sharing>`
      : `:clipboard: *Your Video Script Library:*\n_(your custom script library will be shared shortly — your contact will message you here)_`;
    if (publicChannelId) {
      await slack('chat.postMessage', {
        channel: publicChannelId,
        text: `Welcome to RequityAI, ${contactName || companyName}! :wave:\n\nWe're really excited to have ${companyName} on board and we're looking forward to the opportunity to get you real results. Let's get to work.\n\n*What this channel is for*\nThis is your dedicated space for everything related to your campaigns. We'll use it to:\n\n\u2022 Keep you updated on campaign progress and performance\n\u2022 Notify you the moment your ads go live\n\u2022 Share optimisation decisions and what's working\n\u2022 Answer any questions you have along the way\n\nWhenever you have an update for us or a question, just message here and we'll get back to you promptly. You won't need to chase us \u2014 we'll be in touch proactively.\n\n*To get started, here is everything you need:*\n\n:clipboard: *Facebook Setup Guide* (no Business Portfolio yet):\n<https://drive.google.com/file/d/1erR8MZx_SiuEpqj5wyGPJE6d9I1Q53aB/view?usp=drivesdk>\n\n:clipboard: *Facebook Access Guide* (already have a Business Portfolio):\n<https://drive.google.com/file/d/18UTBCKYjrMC3ZJGS96xBgXaJm2Samusz/view?usp=drivesdk>\n\n${scriptLine}\n\n:file_folder: *Your Google Drive folder for video uploads* will be shared here shortly.\n\nOnce you have completed the Facebook access steps and uploaded your first videos, message us here and we will begin your campaign build within 24 hours.`
      });
    }

    // 7. Post action instruction to team channel
    if (privateChannelId) {
      const guestNote = contactEmail ? `Email: *${contactEmail}*` : `_(no email — check SS)_`;
      const pubRef = publicChannelId ? `<#${publicChannelId}>` : `#client-${slug}`;
      await slack('chat.postMessage', {
        channel: privateChannelId,
        text: `\u2705 *${companyName}* \u2014 internal team channel ready.\n\n\u26a0\ufe0f *ACTION REQUIRED:*\nInvite the client as a *single-channel guest* to ${pubRef}:\n1. Open #client-${slug} \u2192 Members \u2192 Invite People\n2. Enter client email \u2192 select \u201cSingle-channel guest\u201d\n${guestNote}\n\n\ud83d\udccb SS Client: \`${clientId}\`\n\ud83d\udccb SS Onboarding: \`${onboardingId}\`\n\ud83d\uddc2\ufe0f Drive folder auto-creates within 1hr.`
      });
    }

    // 8. Write client channel ID to SS Client record
    if (publicChannelId) {
      await ss('PATCH', `/applications/${CLIENTS_APP}/records/${clientId}/`, {
        slack_channel_id: publicChannelId
      });
    }

    // 9. Mark Pipeline won_processed = true
    await ss('PATCH', `/applications/${PIPELINE_APP}/records/${pipelineId}/`, { won_processed: true });

    result.slack_ok = slackErrors.length === 0;
    if (slackErrors.length > 0) result.slack_errors = slackErrors;
    result.ok = true;

  } catch (err) {
    result.error = err.message;
    if (result.client_id) {
      try {
        await ss('PATCH', `/applications/${PIPELINE_APP}/records/${pipelineId}/`, { won_processed: true });
      } catch (e2) { /* ignore */ }
    }
  }

  results.push(result);
}

return [{ json: { count: results.length, processed: results } }];

