  url: `https://app.smartsuite.com/api/v1/applications/${CAMPAIGNS_APP}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 200, offset: 0}}
});

// Fetch all tasks
const taskRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${TASKS_APP}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 500, offset: 0}}
});

const issues = [];

// 1. Live campaigns with no metrics for 7+ days
for (const c of (campRes.items || [])) {
  if (c.status !== 'Live') continue;
  const lastPull = c.last_pull_date ? new Date(c.last_pull_date) : null;
  if (!lastPull) {
    issues.push(`â ï¸ *${c.title || 'Unknown'}* â Live campaign, NEVER had metrics pulled`);
  } else {
    const daysSincePull = Math.round((now - lastPull) / (1000 * 60 * 60 * 24));
    if (daysSincePull >= 7) {
      issues.push(`â ï¸ *${c.title || 'Unknown'}* â Live campaign, metrics ${daysSincePull} days stale`);
    }
  }
}

// 2. Done tasks with no completed_date
for (const t of (taskRes.items || [])) {
  if (t.status === 'Done' && !t.completed_date) {
    issues.push(`ð *${t.title || 'Untitled'}* â Marked Done but no completed date`);
  }
}

// 3. Blocked tasks older than 48 hours
for (const t of (taskRes.items || [])) {
  if (t.status !== 'Blocked') continue;
  const updated = t.last_updated ? new Date(t.last_updated) : null;
  if (updated) {
    const hoursBlocked = (now - updated) / (1000 * 60 * 60);
    if (hoursBlocked >= 48) {
      issues.push(`ð« *${t.title || 'Untitled'}* â Blocked for ${Math.round(hoursBlocked)}h. Reason: ${t.blocker_reason || 'None given'}`);
    }
  }
}

// 4. Overdue tasks (past due date, still To Do or In Progress)
for (const t of (taskRes.items || [])) {
  if (t.status !== 'To Do' && t.status !== 'In Progress') continue;
  const dueStr = t.due_date?.from_date?.date;
  if (!dueStr) continue;
  const due = new Date(dueStr);
  if (due < now) {
    const daysOverdue = Math.round((now - due) / (1000 * 60 * 60 * 24));
    issues.push(`ð´ *${t.title || 'Untitled'}* â ${daysOverdue} day(s) overdue (due ${dueStr})`);
  }
}

if (issues.length === 0) return [{json: {skip: true, msg: 'All clean â no hygiene issues'}}];

return [{json: {
  channel: OPS_CHANNEL,
  message: `ð§¹ *Daily Data Hygiene Report*\n\n${issues.length} issue(s) found:\n\n${issues.join('\n')}\n\n_Fix these in SmartSuite before end of day._`
}}];

