const SS_TOKEN = "Token <REDACTED>";
const SS_ACCOUNT = "52739";
const CAMPAIGNS_APP = "69ce678977bf866e34b46f68";

const now = new Date();
const cutoff = new Date(now);
cutoff.setDate(now.getDate() - 28);
const cutoffDate = cutoff.toISOString().slice(0, 10);

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${CAMPAIGNS_APP}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 200, offset: 0}}
});

const campaigns = res.items || [];

// SS date fields return {date: "YYYY-MM-DD", time: null} objects, not strings
const getDateStr = (val) => {
  if (!val) return null;
  if (typeof val === 'string') return val.slice(0, 10);
  if (val.date) return val.date.slice(0, 10);
  return null;
};

const fatigued = campaigns.filter(c => {
  const ld = getDateStr(c.launch_date);
  if (!ld || ld > cutoffDate) return false;
  const st = ((c.status && c.status.value) || c.status || '').toLowerCase();
  return st !== 'ended' && st !== 'paused' && st !== 'complete' && st !== 'completed';
});

if (fatigued.length === 0) return [];

const lines = fatigued.map(c => {
  const client = Array.isArray(c.client) && c.client.length > 0
    ? (typeof c.client[0] === 'object' ? c.client[0].title || 'Unknown' : c.client[0])
    : 'Unknown';
  const ldStr = getDateStr(c.launch_date);
  const days = ldStr ? Math.floor((now - new Date(ldStr)) / 86400000) : '?';
  return `• ${c.title || 'Unnamed'} (${client}) — ${days} days running`;
});

return [{
  json: {
    count: fatigued.length,
    summary: lines.join('\n'),
    check_date: now.toISOString().slice(0, 10)
  }
}];

