  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${CAMPAIGNS_APP}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 200, offset: 0}}
});

const messages = [];

for (const client of (clientRes.items || [])) {
  const clientName = client.title || 'Unknown';
  const clientChannel = client.slack_channel_id;
  if (!clientChannel) continue; // Can't message without a channel
  const updated = new Date(client.last_updated || 0);

  // MILESTONE 1: Onboarding complete â welcome message
  if (client.onboarding_complete && !client.welcome_sent && updated > twelveHoursAgo) {
    messages.push({json: {
      channel: clientChannel,
      message: `ð *Welcome aboard, ${clientName}!*\n\nYour onboarding is complete. Here's what happens next:\n\n1. We're building your 3-campaign stack (TOF + MOF + BOF)\n2. You'll see a QA notification when campaigns are ready for final check\n3. Once approved, campaigns go live and we'll send your first performance report 7 days after launch\n\nWe'll keep you updated right here in this channel. Questions? Just message here.`,
      flag: 'welcome_sent'
    }});
  }

  // MILESTONE 2: Campaign launched â notify client
  const clientCampaigns = (campRes.items || []).filter(c => {
    const cids = Array.isArray(c.client) ? c.client : [];
    return cids.includes(client.id);
  });

  for (const camp of clientCampaigns) {
    const campUpdated = new Date(camp.last_updated || 0);
    if (camp.status === 'Live' && !camp.client_launch_notified && campUpdated > twelveHoursAgo) {
      const funnelLabel = camp.funnel_stage === 'TOF' ? 'Top of Funnel (Educational Video Views)'
        : camp.funnel_stage === 'MOF' ? 'Middle of Funnel (Retargeting)'
        : camp.funnel_stage === 'BOF' ? 'Bottom of Funnel (Lead Generation)'
        : camp.funnel_stage || 'Campaign';

      messages.push({json: {
        channel: clientChannel,
        message: `ð *Campaign Live: ${camp.title}*\n\n*Type:* ${funnelLabel}\n*Market:* ${camp.market || 'Your market'}\n\nThis campaign is now running. We'll monitor performance daily and send you a report every 7 days.\n\nFirst report due: ${(() => { const d = new Date(); d.setDate(d.getDate() + 7); return d.toISOString().slice(0,10); })()}`,
        campaignId: camp.id,
        flag: 'client_launch_notified'
      }});
    }
  }
}

// Also prepare Andrew DM summary
if (messages.length > 0) {
  messages.push({json: {
    isDM: true,
    message: `ð¬ *${messages.length} client communication(s) sent automatically*\n\n${messages.filter(m => !m.json.isDM).map(m => 'â¢ ' + m.json.message.split('\n')[0]).join('\n')}`
  }});
}

return messages.length > 0 ? messages : [{json: {skip: true}}];

