// Run Once for All Items — match all clients to their public channels
const splitItems = $('Split Out').all();
const createItems = $('Create Public Slack Channel').all();
const lookupItems = $input.all(); // All channels from Lookup Public (48 per client run)

const result = [];
for (let i = 0; i < splitItems.length; i++) {
  const clientTitle = splitItems[i].json.title || '';
  const createResponse = createItems[i]?.json;
  const expectedName = ('client-' + clientTitle.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '')).substring(0, 80);

  let channelId = null;
  let channelName = expectedName;

  if (createResponse?.ok === true && createResponse.channel?.id) {
    channelId = createResponse.channel.id;
    channelName = createResponse.channel.name;
  } else {
    const found = lookupItems.find(item => item.json.name === expectedName);
    if (found) { channelId = found.json.id; channelName = found.json.name; }
  }

  if (channelId) {
    result.push({ json: {
      id: channelId,
      name: channelName,
      client_title: clientTitle,
      record_id: splitItems[i].json.id || ''
    }});
  }
}
return result;

// Run Once for All Items
// Create Private inputs (4 items, one per client) — ok:true or name_taken
// Lookup Private is HTTP Request: returns 1 item with {ok, channels:[...]}
const splitItems = $('Split Out').all();
const createPrivItems = $input.all(); // from Create Private (4 items)
const extractPubItems = $('Extract Public ID').all();

// Unwrap the Slack API response from Lookup Private HTTP node
const lookupResponse = $('Lookup Private Channel').all();
const allPrivChannels = lookupResponse.flatMap(r => r.json && r.json.channels ? r.json.channels : []);

const result = [];
for (let i = 0; i < splitItems.length; i++) {
  const clientTitle = splitItems[i].json.title || '';
  const createResponse = createPrivItems[i]?.json;
  const publicChannelId = extractPubItems[i]?.json?.id;
  const recordId = splitItems[i].json.id || '';

  const expectedName = ('team-' + clientTitle.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '').replace(/-+/g, '-').replace(/^-|-$/g, '')).substring(0, 80);

  let channelId = null;

  if (createResponse?.ok === true && createResponse.channel?.id) {
    // Freshly created channel — bot is member automatically
    channelId = createResponse.channel.id;
  } else {
    // name_taken — find it in the lookup results
    const found = allPrivChannels.find(ch => ch.name === expectedName);
    if (found) channelId = found.id;
  }

  if (channelId) {
    result.push({ json: {
      private_channel_id: channelId,
      public_channel_id: publicChannelId,
      record_id: recordId,
      title: clientTitle
    }});
  }
}
return result;

// Restore proper channel data after Invite step
// Carry through all fields needed by downstream nodes
const extractPrivItems = $('Extract Private ID').all();
const splitItems = $('Split Out').all();

return extractPrivItems.map((item, i) => ({
  json: {
    ...item.json,
    drive_folder_url: splitItems[i]?.json?.drive_folder_url || '',
    email: splitItems[i]?.json?.email || ''
  }
}));

const SS_TOKEN = "Token <REDACTED>";
const SS_ACCOUNT = "52739";
const CAMPAIGNS_APP = "69ce678977bf866e34b46f68";
const TASKS_APP = "69ce67b3fec5b91842ebaf03";
const OPS_CHANNEL = "C0AKWU4835E";

const today = new Date();
today.setHours(0,0,0,0);
const todayStr = today.toISOString().slice(0, 10);

// Fetch live campaigns
const campRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${CAMPAIGNS_APP}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 200, offset: 0}}
});
const liveCampaigns = (campRes.items || []).filter(c => c.status === 'Live');

// Fetch existing tasks to avoid duplicates
const taskRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${TASKS_APP}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 500, offset: 0}}
});
const existingTaskTitles = new Set((taskRes.items || []).filter(t => t.due_date?.from_date?.date === todayStr).map(t => t.title));

const createdTasks = [];

// TASK 1: For each campaign due for review today (day 6 = pull metrics day, review on day 7)
// Pull metrics 1 day BEFORE each review is due
for (const camp of liveCampaigns) {
  const launchStr = camp.launch_date || camp.due_date?.from_date?.date;
  if (!launchStr) continue;
  const launch = new Date(launchStr);
  launch.setHours(0,0,0,0);
  const daysSinceLaunch = Math.round((today - launch) / (1000 * 60 * 60 * 24));

  // Metrics pull: 1 day before each 7-day review (day 6, 13, 20, 27...)
  if (daysSinceLaunch >= 6 && (daysSinceLaunch % 7 === 6)) {
    const taskTitle = `Pull Metrics â ${camp.title || 'Unknown'} (Day ${daysSinceLaunch + 1} review)`;
    if (!existingTaskTitles.has(taskTitle)) {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `https://app.smartsuite.com/api/v1/applications/${TASKS_APP}/records/`,
        headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
        body: {
          title: taskTitle,
          status: 'To Do',
          type: 'Update SmartSuite Records',
          task_category: 'Optimization',
          priority: 'High',
          assigned_to_select: 'VA',
          campaign: [camp.id],
          client: Array.isArray(camp.client) ? camp.client : [],
          due_date: {from_date: {date: todayStr}}
        }
      });
      createdTasks.push(taskTitle);
    }
  }

  // Creative fatigue check: every 28 days from launch
  if (daysSinceLaunch >= 28 && daysSinceLaunch % 28 === 0) {
    const fatigueTitle = `Creative Fatigue Check â ${camp.title || 'Unknown'} (${daysSinceLaunch} days live)`;
    if (!existingTaskTitles.has(fatigueTitle)) {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `https://app.smartsuite.com/api/v1/applications/${TASKS_APP}/records/`,
        headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
        body: {
          title: fatigueTitle,
          status: 'To Do',
          type: 'Campaign Review',
          task_category: 'Optimization',
          priority: 'Normal',
          assigned_to_select: 'VA',
          campaign: [camp.id],
          client: Array.isArray(camp.client) ? camp.client : [],
          due_date: {from_date: {date: todayStr}}
        }
      });
      createdTasks.push(fatigueTitle);
    }
  }
}

// TASK 2: Ad account policy compliance â for any client with 5+ live campaigns, check every 14 days
const clientCampaignCounts = {};
for (const c of liveCampaigns) {
  const cIds = Array.isArray(c.client) ? c.client : [];
  for (const cid of cIds) {
    clientCampaignCounts[cid] = (clientCampaignCounts[cid] || 0) + 1;
  }
}
// Only create compliance tasks on even-numbered days of the month (pseudo 14-day cadence)
if (today.getDate() % 14 === 0) {
  for (const [clientId, count] of Object.entries(clientCampaignCounts)) {
    if (count >= 5) {
      const compTitle = `Ad Account Policy Compliance Check â Client ${clientId.slice(-6)}`;
      if (!existingTaskTitles.has(compTitle)) {
        await this.helpers.httpRequest({
          method: 'POST',
          url: `https://app.smartsuite.com/api/v1/applications/${TASKS_APP}/records/`,
          headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
          body: {
            title: compTitle,
            status: 'To Do',
            type: 'QA Campaign',
            task_category: 'Admin',
            priority: 'Normal',
            assigned_to_select: 'VA',
            client: [clientId],
            due_date: {from_date: {date: todayStr}}
          }
        });
        createdTasks.push(compTitle);
      }
    }
  }
}

// TASK 3: Stale task review â every 7 days (day of month divisible by 7)
if (today.getDate() % 7 === 0) {
  const staleTitle = `Review Stale Tasks and Update Statuses â ${todayStr}`;
  if (!existingTaskTitles.has(staleTitle)) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://app.smartsuite.com/api/v1/applications/${TASKS_APP}/records/`,
      headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
      body: {
        title: staleTitle,
        status: 'To Do',
        type: 'Admin',
        task_category: 'Admin',
        priority: 'Normal',
        assigned_to_select: 'VA',
        due_date: {from_date: {date: todayStr}}
      }
    });
    createdTasks.push(staleTitle);
  }
}

if (createdTasks.length === 0) return [{json: {skip: true, msg: 'No recurring tasks due today'}}];

return [{json: {
  channel: OPS_CHANNEL,
  message: `ð *${createdTasks.length} recurring task(s) created for ${todayStr}*\n\n${createdTasks.map(t => 'â¢ ' + t).join('\n')}\n\n_All event-driven based on campaign launch dates. Check Tasks app._`
}}];

