const SS_TOKEN = 'Token <REDACTED>';
const SS_ACCOUNT = '52739';
const REVIEWS_APP = '69ce67e01cc0855f89fee02e';
const CAMPAIGNS_APP = '69ce678977bf866e34b46f68';
const TASKS_APP = '69ce67b3fec5b91842ebaf03';
const OPS_CHANNEL = 'C0AKWU4835E';

const res = await this.helpers.httpRequest({method:'POST',url:`https://app.smartsuite.com/api/v1/applications/${REVIEWS_APP}/records/list/`,headers:{'Authorization':SS_TOKEN,'ACCOUNT-ID':SS_ACCOUNT,'Content-Type':'application/json'},body:{filter:{operator:'and',fields:[]},pagination:{limit:200,offset:0}}});

const records = (res.items || []).filter(r => r.decision && r.decision.trim() !== '' && !r.decision_notification_sent);
const results = [];

for (const r of records) {
  const d = r.decision.trim();
  const cids = Array.isArray(r.campaign) ? r.campaign : [];
  let cname = 'Unknown', cid = null, clids = [], fs = '';
  if (cids.length > 0) {
    cid = cids[0];
    try {
      const c = await this.helpers.httpRequest({method:'GET',url:`https://app.smartsuite.com/api/v1/applications/${CAMPAIGNS_APP}/records/${cid}/`,headers:{'Authorization':SS_TOKEN,'ACCOUNT-ID':SS_ACCOUNT,'Content-Type':'application/json'}});
      cname = c.title || cname; clids = Array.isArray(c.client) ? c.client : []; fs = c.funnel_stage || '';
    } catch(e) {}
  }

  let msg = '';
  if (d === 'Cut') {
    if (cid) await this.helpers.httpRequest({method:'PATCH',url:`https://app.smartsuite.com/api/v1/applications/${CAMPAIGNS_APP}/records/${cid}/`,headers:{'Authorization':SS_TOKEN,'ACCOUNT-ID':SS_ACCOUNT,'Content-Type':'application/json'},body:{status:'Cut'}});
    await this.helpers.httpRequest({method:'POST',url:`https://app.smartsuite.com/api/v1/applications/${TASKS_APP}/records/`,headers:{'Authorization':SS_TOKEN,'ACCOUNT-ID':SS_ACCOUNT,'Content-Type':'application/json'},body:{title:'Cut / Pause Campaign - '+cname,status:'To Do',type:'Cut / Pause Campaign',task_category:'Optimization',funnel_stage:fs,priority:'High',assigned_to_select:'VA',campaign:cid?[cid]:[],client:clids,opt_review:[r.id]}});
    msg = '*Decision: CUT* Campaign: '+cname;
  } else if (d === 'Keep Running') {
    const nd = new Date(); nd.setDate(nd.getDate()+7);
    await this.helpers.httpRequest({method:'PATCH',url:`https://app.smartsuite.com/api/v1/applications/${REVIEWS_APP}/records/${r.id}/`,headers:{'Authorization':SS_TOKEN,'ACCOUNT-ID':SS_ACCOUNT,'Content-Type':'application/json'},body:{next_review_date:nd.toISOString().slice(0,10)}});
    msg = '*KEEP RUNNING* '+cname+' Next review:'+nd.toISOString().slice(0,10);
  }
  await this.helpers.httpRequest({method:'PATCH',url:`https://app.smartsuite.com/api/v1/applications/${REVIEWS_APP}/records/${r.id}/`,headers:{'Authorization':SS_TOKEN,'ACCOUNT-ID':SS_ACCOUNT,'Content-Type':'application/json'},body:{decision_notification_sent:true}});
  if (msg) results.push({json:{ channel:OPS_CHANNEL,message:msg}});
}
return results.length>0?results:[{json:{skip:true}}];

const SS_TOKEN = "Token <REDACTED>";
const SS_ACCOUNT = "52739";
const SS_APP_ID = "69ce5f18cb8a07430bfee02d";

// Stage names for readable output
const STAGE_NAMES = {
  '1': 'Access Setup', '2': 'Video Briefing', '3': 'Awaiting Videos',
  '4': 'Videos Received', '5': 'Campaign Build', '6': 'QA', '7': 'Live'
};

// How many days at each stage before it's considered stale
const STALE_THRESHOLDS = {
  '1': 3, '2': 2, '3': 7, '4': 2, '5': 3, '6': 1, '7': 999
};

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${SS_APP_ID}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 100, offset: 0}}
});

const now = new Date();
const stale = [];

for (const c of (res.items || [])) {
  const stage = c.onboarding_stage || '1';
  if (stage === '7') continue; // Live clients — no stale check needed

  const updated = c.last_updated ? new Date(c.last_updated.on || c.last_updated) : null;
  if (!updated) continue;

  const daysSinceUpdate = (now - updated) / (1000 * 60 * 60 * 24);
  const threshold = STALE_THRESHOLDS[stage] || 3;

  if (daysSinceUpdate >= threshold) {
    stale.push({
      json: {
        client_name: c.title || 'Unknown',
        stage: STAGE_NAMES[stage] || stage,
        days_stuck: Math.floor(daysSinceUpdate),
        threshold,
        record_id: c.id
      }
    });
  }
}

return stale;

