  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${CAMPAIGNS_APP}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 200, offset: 0}}
});
const allCampaigns = campRes.items || [];
const liveCampaigns = allCampaigns.filter(c => c.status === 'Live');

// Fetch all clients
const clientRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://app.smartsuite.com/api/v1/applications/${CLIENTS_APP}/records/list/`,
  headers: {'Authorization': SS_TOKEN, 'ACCOUNT-ID': SS_ACCOUNT, 'Content-Type': 'application/json'},
  body: {filter: {operator: 'and', fields: []}, pagination: {limit: 200, offset: 0}}
});
const clients = clientRes.items || [];

// Group live campaigns by client
const campaignsByClient = {};
for (const c of liveCampaigns) {
  const clientIds = Array.isArray(c.client) ? c.client : [];
  for (const cid of clientIds) {
    if (!campaignsByClient[cid]) campaignsByClient[cid] = [];
    campaignsByClient[cid].push(c);
  }
}

const results = [];

for (const client of clients) {
  if (client.status !== 'Active') continue;
  const clientId = client.id;
  const clientName = client.title || 'Unknown';
  const clientCampaigns = campaignsByClient[clientId] || [];
  if (clientCampaigns.length === 0) continue;

  // Check if any campaign is on a 7-day report cycle
  let reportDue = false;
  for (const camp of clientCampaigns) {
    const launchStr = camp.launch_date;
    if (!launchStr) continue;
    const launch = new Date(launchStr);
    launch.setHours(0,0,0,0);
    const daysSinceLaunch = Math.round((today - launch) / (1000 * 60 * 60 * 24));
    if (daysSinceLaunch >= 7 && daysSinceLaunch % 7 === 0) {
      reportDue = true;
      break;
    }
  }
  if (!reportDue) continue;

  // Build the report
  let totalSpend = 0;
  let totalThruPlays = 0;
  let totalLeads = 0;
  let totalSaves = 0;
  let totalComments = 0;
  let totalDMs = 0;
  const campaignLines = [];

  for (const camp of clientCampaigns) {
    const spend = Number(camp.spend || 0);
    const thruplays = Number(camp.thruplays || 0);
    const cpt = Number(camp.cost_thruplay || 0);
    const leads = Number(camp.leads || 0);
    const saves = Number(camp.saves || 0);
    const comments = Number(camp.comments || 0);
    const dms = Number(camp.dms || 0);
    totalSpend += spend;
    totalThruPlays += thruplays;
    totalLeads += leads;
    totalSaves += saves;
    totalComments += comments;
    totalDMs += dms;

    const funnelTag = camp.funnel_stage ? `[${camp.funnel_stage}]` : '';
    campaignLines.push(`  ${funnelTag} ${camp.title}: $${spend.toFixed(2)} spend | ${thruplays} views | $${cpt.toFixed(3)} CPT${leads > 0 ? ` | ${leads} leads` : ''}`);
  }

  const avgCPT = totalThruPlays > 0 ? (totalSpend / totalThruPlays) : 0;
