// Parse slash command: /done videos edited
// Slack sends: channel_id, text (the part after /done), user_id, user_name
const items = $input.all();
const results = [];

// Action keyword → SmartSuite field slug mapping
const ACTION_MAP = {
  'portfolio access': 'step_business_portfolio_access',
  'ad account visible': 'step_ad_account_visible',
  'facebook page confirmed': 'step_facebook_page_confirmed',
  'instagram connected': 'step_instagram_connected',
  'meta ads installed': 'step_meta_ads_app_installed',
  'leads access': 'step_leads_access_confirmed',
  'lead notifications': 'step_lead_notifications_set',
  'lead centre': 'step_lead_centre_to_crm',
  'lead destination': 'step_lead_destination_confirmed',
  'lead centre connected': 'step_fb_lead_centre_connected',
  'video brief sent': 'step_video_brief_sent',
  'videos received': 'step_videos_received',
  'videos edited': 'step_videos_edited',
  'videos approved': 'step_approved_videos_exist',
  'campaign built': 'step_campaign_built',
  'qa passed': 'step_qa_passed',
  'campaign launched': 'step_campaign_launched',
  'launch notified': 'step_launch_notification_sent',
  'onboarding complete': 'step_onboarding_complete'
};

for (const item of items) {
  const body = item.json.body || item.json;
  const channelId = body.channel_id || body.channel || '';
  const text = (body.text || '').toLowerCase().trim();
  const userName = body.user_name || body.user || 'unknown';

  // Find matching action
  let matchedAction = null;
  let matchedSlug = null;
  for (const [keyword, slug] of Object.entries(ACTION_MAP)) {
    if (text.includes(keyword)) {
      matchedAction = keyword;
      matchedSlug = slug;
      break;
    }
  }

  if (matchedSlug) {
    results.push({
      json: {
        channel_id: channelId,
        action: matchedAction,
        field_slug: matchedSlug,
        user_name: userName,
        original_text: text
      }
    });
  } else {
    // Unknown action — return help text
    const validActions = Object.keys(ACTION_MAP).join(', ');
    results.push({
      json: {
        channel_id: channelId,
        action: null,
        error: 'Unknown action: ' + text + '. Valid actions: ' + validActions,
        user_name: userName
      }
    });
  }
}
return results;

const SS_API_TOKEN = '<REDACTED>';
const SS_ACCOUNT_ID = '52739';
const CLIENTS_APP = '69ce5f18cb8a07430bfee02d';
const ONB_APP = '69db909cd9114601cccb2b57';
const base = 'https://app.smartsuite.com/api/v1/applications/';
const headers = {
  'Authorization': 'Token ' + SS_API_TOKEN,
  'Account-Id': SS_ACCOUNT_ID,
  'Content-Type': 'application/json'
};

const items = $input.all();
const results = [];

for (const item of items) {
  const channelId = item.json.channel_id;
  const fieldSlug = item.json.field_slug;
  const action = item.json.action;

  // Step 1: Find client by slack_channel_id
  const clientSearch = await this.helpers.httpRequest({
    method: 'POST', url: base + CLIENTS_APP + '/records/list/',
    headers, body: {
      filter: { operator: 'and', fields: [
        { field: 'slack_channel_id', comparison: 'is', value: channelId }
      ]}
    }
  });

  if (!clientSearch.items || clientSearch.items.length === 0) {
    results.push({ json: { success: false, error: 'No client found for this channel. Is slack_channel_id set on the Client record?', channel_id: channelId, action: action } });
    continue;
  }

  const client = clientSearch.items[0];
  const clientName = client.title;

  // Step 2: Find onboarding record linked to this client
  const onbSearch = await this.helpers.httpRequest({
    method: 'POST', url: base + ONB_APP + '/records/list/',
    headers, body: {
      filter: { operator: 'and', fields: [
        { field: 'title', comparison: 'contains', value: clientName }
      ]}
    }
  });

  if (!onbSearch.items || onbSearch.items.length === 0) {
    results.push({ json: { success: false, error: 'No onboarding record found for ' + clientName, channel_id: channelId, action: action, client_name: clientName } });
    continue;
  }

  const onbRecord = onbSearch.items[0];

  // Step 3: PATCH the field to "3" (Complete)
  const patchBody = {};
  patchBody[fieldSlug] = '3';

  await this.helpers.httpRequest({
    method: 'PATCH', url: base + ONB_APP + '/records/' + onbRecord.id + '/',
    headers, body: patchBody
  });

  results.push({
    json: {
      success: true,
      client_name: clientName,
      action: action,
      field_slug: fieldSlug,
      record_title: onbRecord.title,
      channel_id: channelId,
      user_name: item.json.user_name
    }
  });
}
return results;

